function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  var TT = ["bolt","cannon","frost","lance","flak"];
  var TD = { bolt:[50,26,8,300,0,0,0,1,1], cannon:[90,60,24,260,90,0,0,1,0], frost:[70,10,12,240,0,30,0,1,1], lance:[120,180,36,360,0,0,1,1,0], flak:[80,40,10,320,70,0,0,0,1] };
  var ET = ["grunt","runner","wisp","brute","splitter","mender"];
  var ED = { grunt:[60,10,4,1,0,1,10], runner:[40,20,4,1,0,2,4], wisp:[50,12,6,2,1,3,3], brute:[150,6,9,3,0,4,3], splitter:[90,8,6,2,0,6,2], mender:[70,8,7,2,0,8,1], splitling:[0,12,1,1,0,0,0] };
  var SL = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function mkRoute(pts) { var p = pts.map(function (q) { return [q[0]*100+50, q[1]*100+50]; }), cum = [0];
    for (var i = 1; i < p.length; i++) cum.push(cum[i-1] + Math.abs(p[i][0]-p[i-1][0]) + Math.abs(p[i][1]-p[i-1][1]));
    return { p: p, cum: cum, len: cum[cum.length-1] }; }
  var GR = mkRoute([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  var AR = mkRoute([[0,6],[21,6],[21,11],[23,11]]);
  function pos(r, d) { var i = 1; while (i < r.cum.length - 1 && r.cum[i] < d) i++;
    var a = r.p[i-1], b = r.p[i], t = d - r.cum[i-1];
    return [a[0] + Math.sign(b[0]-a[0]) * t, a[1] + Math.sign(b[1]-a[1]) * t]; }
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed);
  function genWave(w) { var n = 4 + Math.floor(3 * w / 5), av = [], tot = 0, out = [];
    for (var k = 0; k < ET.length; k++) if (ED[ET[k]][5] <= w) { av.push(ET[k]); tot += ED[ET[k]][6]; }
    for (var i = 0; i < n; i++) { var r = rng() % tot;
      for (var j = 0; j < av.length; j++) { var wt = ED[av[j]][6]; if (r < wt) { out.push(av[j]); break; } r -= wt; } }
    return out; }
  var mult = [0, 1000]; function m(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length-1] * 108 / 100)); return mult[w]; }
  var strat = createStrategy();
  var gold = 250, baseHp = 10, wave = 0, nextId = 1, log = [], enemies = [], queue = [], qi = 0;
  var turrets = []; for (var s = 0; s < 16; s++) turrets.push(null);
  var waves = [null, genWave(1)];
  var fallTick = -1, endTick = maxTicks;
  function armorOf(type, w) { return type === "grunt" ? Math.floor(w / 4) : type === "brute" ? 6 + w : 0; }
  function mkEnemy(type, w, prog, maxHp) { var d = ED[type], r = d[4] ? AR : GR;
    var e = { id: nextId++, type: type, wave: w, maxHp: maxHp, hp: maxHp, speed: d[1], armor: armorOf(type, w), bounty: d[2], leak: d[3], air: d[4], route: r, progress: prog, age: 0, slow: 0, x: 0, y: 0 };
    var q = pos(r, prog); e.x = q[0]; e.y = q[1]; return e; }
  function view(e) { return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor, speed: e.speed, slowed: e.slow, remaining: e.route.len - e.progress }; }
  function tstat(t) { var d = TD[t.type], dmg = d[1]; for (var i = 1; i < t.tier; i++) dmg = Math.floor(dmg * 16 / 10);
    return { dmg: dmg, range: d[3] + 30 * (t.tier - 1) }; }
  for (var tick = 0; tick < maxTicks; tick++) {
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      var st = { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: [], enemies: enemies.map(view), nextWave: waves[wave + 1].slice() };
      for (s = 0; s < 16; s++) st.slots.push({ slot: s, x: SL[s][0], y: SL[s][1], turret: turrets[s] ? { type: turrets[s].type, tier: turrets[s].tier, spent: turrets[s].spent } : null });
      var acts = strat.plan(st);
      if (Array.isArray(acts)) for (var ai = 0; ai < acts.length && ai < 32; ai++) { var a = acts[ai]; if (!a || typeof a !== "object") continue;
        var sl = a.slot; if (typeof sl !== "number" || sl % 1 !== 0 || sl < 0 || sl > 15) continue; var t = turrets[sl];
        if (a.op === "build") { if (t || !TD.hasOwnProperty(a.type) || gold < TD[a.type][0]) continue;
          gold -= TD[a.type][0]; turrets[sl] = { type: a.type, tier: 1, spent: TD[a.type][0], cd: 0 }; log.push([tick, "B", sl, TT.indexOf(a.type)]); if (rec) rec.ev(tick, "B", sl, a.type); }
        else if (a.op === "upgrade") { if (!t || t.tier >= 3) continue; var c = TD[t.type][0] * (t.tier === 1 ? 1 : 2); if (gold < c) continue;
          gold -= c; t.tier++; t.spent += c; log.push([tick, "U", sl, t.tier]); if (rec) rec.ev(tick, "U", sl, t.type); }
        else if (a.op === "sell") { if (!t) continue; gold += Math.floor(t.spent * 70 / 100); turrets[sl] = null; log.push([tick, "S", sl, 0]); if (rec) rec.ev(tick, "S", sl, t.type); } }
      var wl = waves[wave]; for (var i = 0; i < wl.length; i++) queue.push([tick + 4 * i, wave, wl[i]]);
    }
    while (qi < queue.length && queue[qi][0] === tick) { var q = queue[qi++]; enemies.push(mkEnemy(q[2], q[1], 0, Math.floor(ED[q[2]][0] * m(q[1]) / 1000))); }
    var fell = false, keep = [];
    for (i = 0; i < enemies.length; i++) { var e = enemies[i];
      if (fell) { keep.push(e); continue; }
      e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      if (e.progress >= e.route.len) { baseHp -= e.leak; log.push([tick, "L", e.id, baseHp]); if (rec) rec.ev(tick, "L", e.id, baseHp);
        if (baseHp <= 0) { fell = true; } continue; }
      var p = pos(e.route, e.progress); e.x = p[0]; e.y = p[1]; keep.push(e); }
    enemies = keep;
    if (fell) { log.push([tick, "F", wave, 0]); fallTick = tick; endTick = tick; if (rec) rec.snap(tick, enemies, turrets, gold, baseHp, wave, true); break; }
    for (i = 0; i < enemies.length; i++) { e = enemies[i]; e.age++;
      if (e.type === "mender" && e.age % 20 === 0) { if (rec) rec.ev(tick, "H", e.x, e.y);
        for (var j = 0; j < enemies.length; j++) { var o = enemies[j], dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= 22500) o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100)); } } }
    for (s = 0; s < 16; s++) { t = turrets[s]; if (!t) continue;
      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      var d = TD[t.type], ts = tstat(t), tx = SL[s][0] * 100 + 50, ty = SL[s][1] * 100 + 50, r2 = ts.range * ts.range, cands = [];
      for (i = 0; i < enemies.length; i++) { e = enemies[i]; if (e.hp <= 0) continue; if (e.air ? !d[8] : !d[7]) continue;
        dx = e.x - tx; dy = e.y - ty; if (dx * dx + dy * dy <= r2) cands.push(e); }
      if (!cands.length) continue;
      var tgt = null;
      if (strat.target) { var cv = cands.map(view), id = strat.target({ slot: s, type: t.type, tier: t.tier, x: tx, y: ty, range: ts.range }, cv);
        for (i = 0; i < cands.length; i++) if (cands[i].id === id) { tgt = cands[i]; break; } }
      if (!tgt) { tgt = cands[0]; for (i = 1; i < cands.length; i++) if (cands[i].route.len - cands[i].progress < tgt.route.len - tgt.progress) tgt = cands[i]; }
      var hits = [tgt];
      if (d[4] > 0) { hits = []; var sr = d[4] * d[4];
        for (i = 0; i < enemies.length; i++) { e = enemies[i]; if (e.hp <= 0) continue; if (e.air ? !d[8] : !d[7]) continue;
          dx = e.x - tgt.x; dy = e.y - tgt.y; if (dx * dx + dy * dy <= sr) hits.push(e); } }
      for (i = 0; i < hits.length; i++) { e = hits[i]; e.hp -= d[6] ? ts.dmg : Math.max(1, ts.dmg - e.armor); if (d[5]) e.slow = d[5]; }
      t.cd = d[2];
      if (rec) rec.shot(tick, s, t.type, tgt.x, tgt.y, tgt.air);
      var dead = false; for (i = 0; i < enemies.length; i++) if (enemies[i].hp <= 0) { dead = true; break; }
      if (dead) { keep = []; var spawn = [];
        for (i = 0; i < enemies.length; i++) { e = enemies[i]; if (e.hp > 0) { keep.push(e); continue; }
          gold += e.bounty; log.push([tick, "K", e.id, s]); if (rec) rec.ev(tick, "K", e.id, s, e);
          if (e.type === "splitter") for (j = 0; j < 3; j++) spawn.push(mkEnemy("splitling", e.wave, e.progress, Math.max(1, Math.floor(e.maxHp / 4)))); }
        enemies = keep.concat(spawn); }
    }
    for (i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (rec) rec.snap(tick, enemies, turrets, gold, baseHp, wave, false);
  }
  var str = JSON.stringify(log), h = 0x811c9dc5;
  for (i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick, log: log, hash: (h >>> 0).toString(16).padStart(8, "0") };
}
